using System.Collections.ObjectModel;using Microsoft.Extensions.DependencyInjection;using Microsoft.UI.Xaml;using Microsoft.UI.Xaml.Controls;using UPM.Windows.SiteApi;
namespace UPM.SiteManager.Views;
public sealed partial class ActivityPage:Page{private readonly IOperatorContext context=App.Services.GetRequiredService<IOperatorContext>();private readonly ObservableCollection<ActivityRow> rows=[];private bool subscribed;public ActivityPage(){InitializeComponent();LogList.ItemsSource=rows;}private void OnLoaded(object s,RoutedEventArgs e){if(!subscribed){context.Changed+=OnChanged;subscribed=true;}_=RefreshAsync();}private void OnUnloaded(object s,RoutedEventArgs e){if(subscribed){context.Changed-=OnChanged;subscribed=false;}}private void OnChanged(object? s,OperatorContextChangedEventArgs e)=>DispatcherQueue.TryEnqueue(()=>_=RefreshAsync());private void OnRefresh(object s,RoutedEventArgs e)=>_=RefreshAsync();private async Task RefreshAsync(){rows.Clear();var api=context.ActiveClient;if(api is null){Show("Connect to a Site to load operational activity.",InfoBarSeverity.Informational);return;}try{var payload=await api.GetOperationalLogsAsync(context.SelectedEventId,CancellationToken.None);foreach(var x in payload.Items())rows.Add(new ActivityRow{Time=JsonProjection.LocalTime(x.Text("occurred_at","")),Severity=x.Text("severity").ToUpperInvariant(),Service=x.Text("service"),EventType=x.Text("event_type"),Message=x.Text("message"),Correlation=Correlation(x)});CountText.Text=$"{rows.Count} operational records from the last 24 hours";if(rows.Count==0)Show("No operational activity was recorded for this selection.",InfoBarSeverity.Informational);else StateBar.IsOpen=false;}catch(Exception ex){Show(ex.Message,InfoBarSeverity.Error);}}private static string Correlation(System.Text.Json.JsonElement x)=>string.Join(" • ",new[]{("room",x.Text("room_id","")),("device",x.Text("device_id","")),("presentation",x.Text("presentation_id",""))}.Where(v=>v.Item2.Length>0).Select(v=>$"{v.Item1} {v.Item2}"));private void Show(string m,InfoBarSeverity s){StateBar.Title=s==InfoBarSeverity.Error?"LOG API ERROR":"ACTIVITY";StateBar.Message=m;StateBar.Severity=s;StateBar.IsOpen=true;}}
public sealed class ActivityRow{public string Time{get;set;}="";public string Severity{get;set;}="";public string Service{get;set;}="";public string EventType{get;set;}="";public string Message{get;set;}="";public string Correlation{get;set;}="";}
